-- Estrutura gerada em 18/10/2026 do banco onde o Financeiro estava (agenda-pro / vuwgxndahrzinfdlapxz): 3 sequências,
-- 28 tabelas fin_*, regras, 42 vínculos e 44 índices. Só acréscimos (nenhuma tabela fin_* existia no destino).
-- Diferença proposital: as tabelas não ficam abertas para quem não está logado (anon) — o convite usa funções, não tabelas.
-- APLICADO em 18/10/2026 no cobranca-pro como migration `financeiro_001_estrutura` (este arquivo; o RLS e o revoke anon
-- do fim foram aplicados num laço equivalente). Antes: extensão pg_trgm no esquema extensions (usada por 1 função).

create sequence if not exists public.fin_auditoria_id_seq as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1;
